DECLARE @a int,@s binary(8);SELECT TOP(1) @a=MaTK,@s=SecurityStamp FROM dbo.TAIKHOAN WHERE MaVT='ADMIN' AND HoatDong=1 ORDER BY MaTK;IF (SELECT SoLuongTon FROM dbo.NGUYENVATLIEU WHERE MaNVL='NVL99')<>0 OR EXISTS(SELECT 1 FROM dbo.MaterialOpening WHERE MaNVL='NVL99') OR EXISTS(SELECT 1 FROM dbo.G03OperationReceipt WHERE RequestId='11111111-1111-1111-1111-111111111109') THROW 52999,'Opening partial state',1;
